public class MuxerDurationProbe {public static void main(String[] a)throws Exception {Class<?> c=Class.forName("androidx.media3.muxer.Boxes");Method m=c.getDeclaredMethod("convertPresentationTimestampsToDurationsVu",List.class,int.class,int.class,long.class);m.setAccessible(true);List<BufferInfo> frames=new ArrayList<>();for(long pts:new long[]{0,208333,416667,625000,833333,1000000})frames.add(new BufferInfo(pts,1,0));System.out.println("old first fragment "+m.invoke(null,frames.subList(0,5),90000,1,-9223372036854775807L));System.out.println("new single fragment "+m.invoke(null,frames,90000,1,1200000L));}}
